# helper: replace text but preserve roughly first-run font formatting
def set_text_preserve(shape, new_text):
    tf = shape.text_frame
    # capture styles from first run/paragraph
    style = {}
    p0 = tf.paragraphs[0] if tf.paragraphs else None
    if p0 and p0.runs:
        r0 = p0.runs[0]
        f = r0.font
        style = {
            'name': f.name,
            'size': f.size,
            'bold': f.bold,
            'italic': f.italic,
            'underline': f.underline,
            'color_type': getattr(f.color, 'type', None),
            'rgb': getattr(f.color, 'rgb', None),
        }
    elif p0:
        style = {'size': None}
    align = p0.alignment if p0 else None

    tf.clear()
    lines = new_text.split('\n')
    for idx, line in enumerate(lines):
        p = tf.paragraphs[0] if idx == 0 else tf.add_paragraph()
        if align is not None:
            p.alignment = align
        r = p.add_run()
        r.text = line
        f = r.font
        if style.get('name'):
            f.name = style['name']
        if style.get('size'):
            f.size = style['size']
        if style.get('bold') is not None:
            f.bold = style['bold']
        if style.get('italic') is not None:
            f.italic = style['italic']
        if style.get('underline') is not None:
            f.underline = style['underline']
        if style.get('rgb') is not None:
            try:
                f.color.rgb = style['rgb']
            except Exception:
                pass

# apply replacements
for s_idx, slide in enumerate(prs.slides, 1):
    reps = replacements.get(s_idx, {})
    for shape in slide.shapes:
        if hasattr(shape, 'text') and shape.text in reps:
            set_text_preserve(shape, reps[shape.text])

prs.save(out)
print(out)
